_ok = BookReview(title="T", rating=5, pros=["a"], cons=[], recommended=False)
assert _ok.rating == 5 and _ok.title == "T", "BookReview must accept title, rating, pros, cons and recommended"
for _bad in (0, 6):
    try:
        BookReview(title="T", rating=_bad, pros=[], cons=[], recommended=True)
    except ValidationError:
        pass
    else:
        raise AssertionError(f"rating={_bad} must be rejected - use Field(ge=1, le=5)")
try:
    BookReview(title="T", rating=3, pros=[], cons=[])
except ValidationError:
    pass
else:
    raise AssertionError("recommended must be a required bool field")
_c = FakeOpenAI()
_r = analyze_review(_c, "Great book, a bit dated.")
assert isinstance(_r, BookReview), "analyze_review must return a BookReview instance"
assert _c.chat.completions.last_request["response_format"] == {"type": "json_object"}, "use JSON mode: response_format={'type': 'json_object'}"
assert any("Great book, a bit dated." in _m["content"] for _m in _c.chat.completions.last_request["messages"]), "send the review text in a message"
assert _r.rating == 4 and _r.recommended is True and _r.pros == ["Clear explanations", "Practical projects"], "parse the JSON reply with BookReview.model_validate_json"
